```

And `StructAtOffset` does:
```cpp
template <typename Type>
static inline const Type& StructAtOffset (const void *base, const OffsetTo<Type, HBUINT32, false> &offset)
{
    return *reinterpret_cast<const Type *> ((const char *) base + (unsigned int) offset);
